mapper.update:
UPDATE TB_ITEM_SHARE
SET PERMISSION = #{permission},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}

mapper.delete:
DELETE FROM TB_ITEM_SHARE
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}

mapper.select:
SELECT COUNT(*) > 0
FROM TB_ITEM_SHARE
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}

SELECT PERMISSION
FROM TB_ITEM_SHARE
WHERE ITEM_ID = #{itemId}
  AND USERNAME = #{username}
